import type { UserRole } from '~/client';

/**
 * Position a new assignment starts with. The server never defaults a position — this map is the
 * single source of the role defaults, prefilled into the assign forms so the operator sees (and can
 * edit) what will be saved. Subcontractor canvassers deliberately share the "Canvasser" label: the
 * customer-facing roster does not distinguish subcontracted staff.
 *
 * Admins are deliberately absent: they are hand-picked for the customer-facing HQ section, so an
 * admin assignment starts with no position and stays off the roster until one is given.
 */
export const positionDefaultsByRole: Partial<Record<UserRole, string>> = {
  manager: 'Field Manager',
  canvasser: 'Canvasser',
  subcontractor_canvasser: 'Canvasser',
};

/**
 * Unknown / absent roles fall back to an empty string, NOT to `snakeCaseToCapitalizedCase` as the
 * display-config convention prescribes: this value is saved, not rendered. Deriving a label here
 * would hand an admin the position "Admin" and silently publish them to the customer-facing roster.
 */
export function defaultPositionForRole(role: UserRole | undefined): string {
  if (!role) return '';
  return positionDefaultsByRole[role] ?? '';
}
